//
// Look up a Pokemon species' extracted front sprite, if one is present
// in the build. Companion to `species_sprite_lookup.cpp`, which is
// regenerated by `tools/gen_sprite_lookup.py` on every `make gba`.
//
// `species_sprite_for(id)` returns the `bn::sprite_item*` produced by
// butano's grit pipeline from `graphics/sprites/species_NNN.bmp`, or
// nullptr when no BMP was extracted for that species. Call sites pick
// `bn::sprite_items::silhouette` as the fallback — see
// `pokemon_edit_scene::redraw_right_panel`.
//
// See docs/frontend-gba-plan.md §"Checkpoint #6 — Sprites" for the
// extraction + lookup pipeline.

#ifndef PKSAVE_GBA_SPECIES_SPRITE_LOOKUP_HPP
#define PKSAVE_GBA_SPECIES_SPRITE_LOOKUP_HPP

#include <bn_sprite_item.h>

namespace pksave_gba {
namespace sprite_lookup {

const bn::sprite_item* species_sprite_for(int id);

}  // namespace sprite_lookup
}  // namespace pksave_gba

#endif  // PKSAVE_GBA_SPECIES_SPRITE_LOOKUP_HPP
